CREATE OR REPLACE FUNCTION public.pro_home_profile(_visit uuid) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE v public.visits; BEGIN SELECT * INTO v FROM public.visits WHERE id=_visit; IF NOT FOUND OR NOT (v.assigned_pro_id=auth.uid() OR public.pro_on_cleaning_team_visit(v.id,auth.uid())) OR NOT public.pro_access_window_open(v.id,auth.uid()) THEN RETURN NULL; END IF; RETURN (SELECT profile FROM public.home_notes WHERE user_id=v.user_id); END $$;
REVOKE ALL ON FUNCTION public.pro_home_profile(uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.pro_home_profile(uuid) TO authenticated,service_role;
ALTER POLICY member_checkin_read ON public.member_visit_checkins USING(user_id=auth.uid() OR public.has_role(auth.uid(),'admin') OR (pro_id=auth.uid() AND public.pro_access_window_open(visit_id,auth.uid())));
CREATE OR REPLACE FUNCTION public.first_three_checkin_reply(_phone text,_body text,_sid text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE c public.member_visit_checkins; v public.visits; val integer; pending integer; BEGIN
IF auth.role() IS DISTINCT FROM 'service_role' THEN RAISE EXCEPTION 'forbidden'; END IF;
IF trim(_body) !~ '^[1-5]$' THEN RETURN jsonb_build_object('handled',false); END IF;
PERFORM pg_advisory_xact_lock(hashtext(right(regexp_replace(_phone,'\D','','g'),10)));
IF EXISTS(SELECT 1 FROM visit_ratings WHERE raw_identifier='sms:'||_sid) THEN RETURN jsonb_build_object('handled',true,'duplicate',true); END IF;
SELECT count(*) INTO pending FROM member_visit_checkins mc JOIN profiles p ON p.user_id=mc.user_id JOIN sms_outbox o ON o.idempotency_key='sched-first-three:'||mc.visit_id WHERE right(regexp_replace(p.phone,'\D','','g'),10)=right(regexp_replace(_phone,'\D','','g'),10) AND o.status='sent' AND mc.scored_at IS NULL AND NOT mc.is_test AND mc.release_at<=now() AND mc.release_at>now()-interval '7 days';
IF pending>1 THEN RETURN jsonb_build_object('handled',true,'ambiguous',true); END IF;
SELECT mc.* INTO c FROM member_visit_checkins mc JOIN profiles p ON p.user_id=mc.user_id JOIN sms_outbox o ON o.idempotency_key='sched-first-three:'||mc.visit_id WHERE right(regexp_replace(p.phone,'\D','','g'),10)=right(regexp_replace(_phone,'\D','','g'),10) AND o.status='sent' AND mc.scored_at IS NULL AND NOT mc.is_test AND mc.release_at<=now() AND mc.release_at>now()-interval '7 days' ORDER BY mc.release_at DESC LIMIT 1 FOR UPDATE OF mc;
IF c.visit_id IS NULL THEN RETURN jsonb_build_object('handled',false); END IF;
val:=trim(_body)::integer; UPDATE member_visit_checkins SET score=val,scored_at=now() WHERE visit_id=c.visit_id AND scored_at IS NULL; IF NOT FOUND THEN RETURN jsonb_build_object('handled',true,'duplicate',true); END IF;
INSERT INTO visit_ratings(visit_id,user_id,contractor_id,rating,stars,source,lang,raw_identifier,verified) VALUES(c.visit_id,c.user_id,c.pro_id,val,val,'sms_reply',public.user_lang(c.user_id),'sms:'||_sid,true);
IF val<=3 THEN SELECT * INTO v FROM visits WHERE id=c.visit_id; IF NOT EXISTS(SELECT 1 FROM redo_requests WHERE visit_id=v.id AND status<>'canceled') THEN INSERT INTO redo_requests(visit_id,user_id,pro_id,note,source,requested_at,due_at,is_test_row) VALUES(v.id,c.user_id,c.pro_id,'First-three-visit score '||val||'; contact member and arrange free return within 48 hours.','sms',now(),now()+interval '48 hours',false); END IF;
INSERT INTO admin_alerts(alert_type,level,category,title,body,action_label,action_url,dedupe_key,context) VALUES('first_three_low_score','critical','operations','Visit scored '||val||'/5 — redo follow-up','Member rated an early visit 1–3. Contact them immediately; return within 48 hours, free. / El miembro calificó una visita inicial con 1–3. Contáctalo de inmediato; regreso gratis en 48 horas.','Open redo','/admin/redos','early-score:'||c.visit_id,jsonb_build_object('visit_id',c.visit_id,'pro_id',c.pro_id,'score',val)) ON CONFLICT DO NOTHING; END IF;
RETURN jsonb_build_object('handled',true,'score',val,'visit_id',c.visit_id); END $$;
REVOKE ALL ON FUNCTION public.first_three_checkin_reply(text,text,text) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.first_three_checkin_reply(text,text,text) TO service_role;